mapper.select:
SELECT COUNT(1) FROM db_database
WHERE system_id = #{systemId} AND db_user = #{dbUser} AND env = #{env}
AND id != #{excludeId}

mapper.update:
UPDATE db_database d
SET d.table_count = (SELECT COUNT(1) FROM db_table_doc t WHERE t.database_id = #{id} AND t.status = 1)
WHERE d.id = #{id}
